266→        let store = FeedbackStore::new(temp.path().join("feedback.jsonl"));
267→
268→        for i in 0..5 {
269→            store
270→                .append(&FeedbackEntry::new(format!("entry {}", i)))
271→                .unwrap();
272→        }
273→
274→        let entries = store.list_all().unwrap();
