    #[test]
    fn registry_caches_remote_templates() {
        let server = MockServer::start();

        let template_yaml = r#"
name: cached-tool
description: "Cached tool"
category: tools
step:
  command: cached-tool run
"#;

        let mock = server.mock(|when, then| {
            when.method(GET).path("/templates.yml");
