        let sources = vec![TemplateSourceConfig {
            url: server.url("/templates.yml"),
            priority: 50,
            timeout: 30,
            cache: None,
            auth: None,
        }];

        // First load - hits server
        let _remote1 = RemoteLoader::new(&sources, &fetcher, &cache).unwrap();
